func minMoves(nums []int, k int) int {
	arr := []int{}
	for i, x := range nums {
		if x != 0 {
			arr = append(arr, i)
		}
	}
	s := make([]int, len(arr)+1)
	for i, x := range arr {
		s[i+1] = s[i] + x
	}
	ans := 1 << 60
	x := (k + 1) / 2
	y := k - x
	for i := x - 1; i < len(arr)-y; i++ {
		j := arr[i]
		ls := s[i+1] - s[i+1-x]
		rs := s[i+1+y] - s[i+1]
		a := (j+j-x+1)*x/2 - ls
		b := rs - (j+1+j+y)*y/2
		ans = min(ans, a+b)
	}
	return ans
}

class Solution:
    def minMoves(self, nums: List[int], k: int) -> int:
        p = [i for i, v in enumerate(nums) if v == 1]
        n = len(p)
        presum = [0] * (n + 1)
        for i in range(n):
            presum[i + 1] = presum[i] + p[i]
        ans = float("inf")
        if k % 2 == 1:
            # i-radius ... i ... i+radius
            radius = (k - 1) // 2
            for i in range(radius, n - radius):
                right = presum[i + radius + 1] - presum[i + 1]
                left = presum[i] - presum[i - radius]
                ans = min(ans, right - left)
            return ans - radius * (radius + 1)
        else:
            # i-radius ... i ... i+radius+1
            radius = (k - 2) // 2
            for i in range(radius, n - radius - 1):
                right = presum[i + radius + 2] - presum[i + 1]
                left = presum[i] - presum[i - radius]
                ans = min(ans, right - left - p[i])
            return ans - radius * (radius + 1) - (radius + 1)
